import { FC } from 'react';

import { theme, Typography } from 'antd';
import { LinkProps } from 'antd/lib/typography/Link';

interface ICopyLinkProps extends LinkProps {
	url: string;
	maxWidth?: number;
	textDecoration?: 'underline' | 'none';
	onLinkCopy?: (event?: React.MouseEvent<HTMLButtonElement>) => void;
}

export const CopyLink: FC<ICopyLinkProps> = ({
	url,
	maxWidth = 150,
	textDecoration = 'underline',
	onLinkCopy,
	...props
}) => {
	const {
		token: { colorPrimary },
	} = theme.useToken();

	return (
		<Typography.Link {...props} href={url} target="_blank" copyable={{ text: url, onCopy: onLinkCopy }}>
			<Typography.Text ellipsis={{ tooltip: url }} style={{ maxWidth, color: colorPrimary, textDecoration }}>
				{url}
			</Typography.Text>
		</Typography.Link>
	);
};
